pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 numTos, uint256 failIndex) public {
        // Bound: at least 2 recipients, one will be the failing callee.
        numTos = bound(numTos, 2, 20);
        failIndex = bound(failIndex, 0, numTos - 1);

        // Deploy a helper that always reverts on low-level call (transferFrom).
        Reverter failing = new Reverter();
        // Deploy a helper that always succeeds (normal token).
        Noop successToken = new Noop();

        address from = address(0x1000);
        address[] memory tos = new address[](numTos);
        uint[] memory values = new uint[](numTos);
        for (uint i = 0; i < numTos; i++) {
            if (i == failIndex) {
                tos[i] = address(failing);
            } else {
                tos[i] = address(successToken);
            }
            values[i] = 1;
        }

        // Ensure the caller is not restricted.
        vm.prank(from);
        bool success;
        try c.transfer(from, address(failing), tos, values) {
            // The correct C should never reach here because one call fails -> revert.
        } catch {
            success = true;
        }
        try c.transfer(from, address(failing), tos, values) returns (bool ok) {
            // Mutant reaches here and returns true.
            success = false;
        } catch {
            success = true;
        }
        assertTrue(success, "transfer did not revert when a sub-call failed");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

contract Noop {
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
}
